/**
 *
 * The useSortableContainer hook manages a sortable list with vanilla pointer events DnD.
 * Supports single-list sorting and multi-list transfers (when used with useDnd coordinator).
 *
 * @module useSortableContainer
 * @group headless
 *
 */
import type { HeadlessInstance } from '@primereact/types/core';
import type { UniqueId } from '@primereact/types/primitive/dnd';
import type { UseDndSortEvent } from './useDnd.types';
/**
 * Defines valid properties in useSortableContainer.
 */
export interface UseSortableContainerProps {
    /**
     * Optional DnD coordinator for multi-container scenarios.
     * Created by useDnd. When omitted, the container works standalone.
     */
    dnd?: unknown;
    /**
     * Unique identifier for this container.
     */
    id?: UniqueId;
    /**
     * Ordered list of items in this container.
     */
    items?: unknown[];
    /**
     * Whether the container is disabled.
     * @default false
     */
    disabled?: boolean;
    /**
     * Controls the placeholder element left behind during drag.
     * - `"empty"` creates an empty element that only preserves the height (default).
     * - `"clone"` creates a visual copy of the dragged item.
     * @default "empty"
     */
    placeholder?: 'clone' | 'empty';
    /**
     * Callback fired when items are reordered within this container.
     * Used in standalone mode (without dnd coordinator).
     */
    onSort?: (event: UseDndSortEvent) => void;
}
/**
 * Defines valid state in useSortableContainer.
 */
export interface UseSortableContainerState {
    /**
     * Whether a drag operation is active in this container.
     */
    dragging: boolean;
}
/**
 * Data attribute props for the sortable container element.
 */
export interface UseSortableContainerRootProps {
    'data-scope': string;
    'data-part': string;
    'data-active'?: string;
    'data-disabled'?: string;
}
/**
 * Per-item DnD props returned by getItemDndProps.
 */
export interface UseSortableItemDndProps {
    onPointerDown?: (e: React.PointerEvent<HTMLElement>) => void;
}
/**
 * Defines the methods and properties exposed by useSortableContainer.
 */
export interface UseSortableContainerExposes {
    /**
     * The reactive container state.
     */
    state: UseSortableContainerState;
    /**
     * Ref to attach to the list DOM element.
     */
    listRef: React.RefObject<HTMLElement | null>;
    /**
     * Returns DnD props (onPointerDown) for a sortable item at the given index.
     */
    getItemDndProps: (index: number) => UseSortableItemDndProps;
    /**
     * Pre-built data attribute props for the container element.
     */
    rootProps: UseSortableContainerRootProps;
}
/**
 * Instance of useSortableContainer headless.
 */
export type UseSortableContainerInstance = HeadlessInstance<UseSortableContainerProps, UseSortableContainerState, UseSortableContainerExposes>;
